-- AGT-003: shipped immutable manifests bind the SQL final gate to the same engine vocabulary as the API.
CREATE TABLE trustwork.agent_engine_manifest (
  module_key text NOT NULL, module_version text NOT NULL, document jsonb NOT NULL, default_control jsonb NOT NULL,
  PRIMARY KEY(module_key,module_version),
  CHECK(document ->> 'key' = module_key AND document ->> 'version' = module_version)
);
ALTER TABLE trustwork.agent_engine_manifest ENABLE ROW LEVEL SECURITY;
ALTER TABLE trustwork.agent_engine_manifest FORCE ROW LEVEL SECURITY;
CREATE POLICY engine_manifest_read ON trustwork.agent_engine_manifest FOR SELECT USING (true);
CREATE POLICY engine_manifest_maintenance ON trustwork.agent_engine_manifest TO trustwork_owner USING (trustwork.maintenance_on()) WITH CHECK (trustwork.maintenance_on());
GRANT SELECT ON trustwork.agent_engine_manifest TO trustwork_app;
