CREATE TRIGGER agent_manifest_immutable BEFORE UPDATE OR DELETE ON trustwork.agent_engine_manifest
  FOR EACH ROW EXECUTE FUNCTION trustwork.forbid_mutation();

-- Extensions have no permissive SQL fallback: their owning activated-version port must be implemented first.
CREATE OR REPLACE FUNCTION trustwork.agent_modules_policy_refusal(p_hub uuid,p_capability_id text,p_kind text,p_company_verified boolean,p_plan text) RETURNS text
LANGUAGE plpgsql STABLE SET search_path = trustwork, pg_temp AS $$
DECLARE v_doc jsonb; v_module text := split_part(p_capability_id,'.',1); v_version text; v_manifest trustwork.agent_engine_manifest%ROWTYPE; v_control jsonb; v_switch jsonb;
BEGIN
  IF p_hub IS NULL THEN RETURN 'capability.unknown'; END IF;
  IF NOT EXISTS (SELECT 1 FROM trustwork.agent_engine_manifest m, jsonb_array_elements(m.document -> 'capabilities') c
    WHERE m.module_key = v_module AND c ->> 'id' = p_capability_id) THEN RETURN 'capability.unknown'; END IF;
  SELECT document INTO v_doc FROM trustwork.agent_policy_current WHERE hub_id = p_hub;
  IF v_doc IS NOT NULL THEN
    SELECT e ->> 'moduleVersion' INTO v_version FROM jsonb_array_elements(v_doc -> 'policy' -> 'enabledModules') e WHERE e ->> 'moduleKey' = v_module;
    SELECT m INTO v_control FROM jsonb_array_elements(v_doc -> 'modules') m WHERE m ->> 'moduleKey' = v_module;
    IF v_version IS NULL OR v_control IS NULL THEN RETURN 'module.not_enabled'; END IF;
    SELECT * INTO v_manifest FROM trustwork.agent_engine_manifest WHERE module_key = v_module AND module_version = v_version;
  ELSE
    -- Exactly one shipped default version. A later multi-version rollout must name its default explicitly.
    IF (SELECT count(*) FROM trustwork.agent_engine_manifest WHERE module_key = v_module) <> 1 THEN RETURN 'capability.unknown'; END IF;
    SELECT * INTO v_manifest FROM trustwork.agent_engine_manifest WHERE module_key = v_module;
    v_control := v_manifest.default_control;
  END IF;
  IF v_manifest.module_key IS NULL OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_manifest.document -> 'capabilities') c
    WHERE c ->> 'id' = p_capability_id) THEN RETURN 'capability.unknown'; END IF;
  IF (v_control ->> 'status') NOT IN ('beta','active') THEN RETURN 'module.not_serving'; END IF;
  IF NOT (v_control -> 'principalKinds') ? p_kind THEN RETURN 'module.not_eligible'; END IF;
  IF (v_control ->> 'verifiedCompanyRequired')::boolean AND p_kind <> 'person' AND NOT coalesce(p_company_verified,false) THEN RETURN 'module.verified_company_required'; END IF;
  IF NOT (v_control -> 'capabilityIds') ? p_capability_id THEN RETURN 'capability.off_for_hub'; END IF;
  SELECT x INTO v_switch FROM jsonb_array_elements(v_doc -> 'capabilities') x WHERE x ->> 'capabilityId' = p_capability_id;
  IF (v_switch ->> 'offForHub')::boolean THEN RETURN 'capability.off_for_hub'; END IF;
  IF (v_switch -> 'offForPrincipalKinds') ? p_kind THEN RETURN 'capability.off_for_principal_kind'; END IF;
  IF p_plan IS NULL OR p_plan <> 'free' THEN RETURN 'capability.off_for_plan'; END IF;
  IF (v_switch -> 'offForPlans') ? p_plan THEN RETURN 'capability.off_for_plan'; END IF;
  RETURN NULL;
END $$;

CREATE FUNCTION trustwork.agent_modules_capability_binding(p_hub uuid,p_capability text) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = trustwork, pg_temp AS $$
  SELECT c FROM trustwork.agent_engine_manifest m CROSS JOIN LATERAL jsonb_array_elements(m.document -> 'capabilities') c
  LEFT JOIN trustwork.agent_policy_current p ON p.hub_id = p_hub
  WHERE c ->> 'id' = p_capability AND p_hub IS NOT NULL
    AND (p.hub_id IS NULL OR EXISTS (SELECT 1 FROM jsonb_array_elements(p.document -> 'policy' -> 'enabledModules') e
      WHERE e ->> 'moduleKey' = m.module_key AND e ->> 'moduleVersion' = m.module_version))
  ORDER BY m.module_version LIMIT 1
$$;

-- Engine-installed handlers are exact versioned bindings, never model-selected authority.
-- No generic effect adapter is shipped. Local occurrence handlers use their own typed runtime.
CREATE TABLE trustwork.agent_effect_handler (
  module_key text NOT NULL,
  module_version text NOT NULL,
  capability_id text NOT NULL,
  provider text NOT NULL,
  operation text NOT NULL,
  PRIMARY KEY(module_key,module_version,capability_id,provider,operation),
  FOREIGN KEY(module_key,module_version) REFERENCES trustwork.agent_engine_manifest(module_key,module_version)
);
ALTER TABLE trustwork.agent_effect_handler ENABLE ROW LEVEL SECURITY;
ALTER TABLE trustwork.agent_effect_handler FORCE ROW LEVEL SECURITY;
CREATE POLICY effect_handler_read ON trustwork.agent_effect_handler FOR SELECT USING (true);
CREATE POLICY effect_handler_maintenance ON trustwork.agent_effect_handler TO trustwork_owner USING (trustwork.maintenance_on()) WITH CHECK (trustwork.maintenance_on());
GRANT SELECT ON trustwork.agent_effect_handler TO trustwork_app;

CREATE FUNCTION trustwork.agent_modules_effect_binding(p_hub uuid,p_capability text,p_provider text,p_operation text) RETURNS boolean
LANGUAGE sql STABLE SET search_path = trustwork, pg_temp AS $$
  SELECT EXISTS (SELECT 1 FROM trustwork.agent_effect_handler h
    WHERE h.capability_id = p_capability AND h.provider = p_provider AND h.operation = p_operation
      AND h.module_key = trustwork.agent_modules_capability_binding(p_hub,p_capability) #>> '{source,moduleKey}'
      AND h.module_version = trustwork.agent_modules_capability_binding(p_hub,p_capability) #>> '{source,moduleVersion}')
$$;

ALTER FUNCTION trustwork.assistant_begin_attempt(uuid,uuid,uuid,bigint) RENAME TO agent_modules_begin_proven_lease;
REVOKE ALL ON FUNCTION trustwork.agent_modules_begin_proven_lease(uuid,uuid,uuid,bigint) FROM PUBLIC,trustwork_app,trustwork_worker;
CREATE FUNCTION trustwork.assistant_begin_attempt(p_intent uuid,p_job uuid,p_hub uuid,p_fence bigint) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = trustwork, pg_temp SET trustwork.maintenance = 'on' AS $$
DECLARE i trustwork.action_intent%ROWTYPE; p trustwork.agent_intent_provenance%ROWTYPE; c jsonb;
BEGIN
  PERFORM 1 FROM trustwork.job WHERE id = p_job AND kind = 'assistant.dispatch' AND state = 'leased'
    AND leased_until > clock_timestamp() AND fencing_token = p_fence AND payload ->> 'intentId' = p_intent::text FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'dispatch lease unavailable' USING ERRCODE = '55P03', HINT = 'assistant.fenced_out'; END IF;
  SELECT * INTO p FROM trustwork.agent_intent_provenance WHERE action_intent_id = p_intent;
  IF p.action_intent_id IS NOT NULL THEN
    PERFORM trustwork.agent_modules_lock_epochs(p.hub_id,NULL,p.principal_person_id,NULL);
    SELECT * INTO i FROM trustwork.action_intent WHERE id = p_intent FOR UPDATE;
    c := trustwork.agent_modules_capability_binding(p.hub_id,i.capability_id);
    IF i.state = 'queued' AND (NOT trustwork.agent_modules_effect_binding(p.hub_id,i.capability_id,i.effect ->> 'provider',i.effect ->> 'operation') OR c IS NULL OR c ->> 'mandateAction' IS DISTINCT FROM i.action
      OR c ->> 'kind' = 'govern' OR c ->> 'confirmation' IN ('first_party_form','first_party_step_up','person_each','person_each_step_up')) THEN
      PERFORM trustwork.assistant_finish_intent(i.id,'revoked','recheck: capability_binding','recheck:capability_binding');
      RETURN jsonb_build_object('status','refused','reason','capability_binding');
    END IF;
  END IF;
  RETURN trustwork.agent_modules_begin_proven_lease(p_intent,p_job,p_hub,p_fence);
END $$;
REVOKE ALL ON FUNCTION trustwork.assistant_begin_attempt(uuid,uuid,uuid,bigint) FROM PUBLIC,trustwork_app;
GRANT EXECUTE ON FUNCTION trustwork.assistant_begin_attempt(uuid,uuid,uuid,bigint) TO trustwork_worker;

-- Participant service transactions hold the same authority epochs through their actual read/mutation.
CREATE FUNCTION trustwork.agent_modules_lock_current_authority(p_hub uuid,p_company uuid,p_connection uuid) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = trustwork, pg_temp SET trustwork.maintenance = 'on' AS $$
DECLARE v_person uuid := trustwork.current_person_id();
BEGIN
  IF v_person IS NULL OR p_hub IS NULL
    OR (p_company IS NOT NULL AND NOT EXISTS (SELECT 1 FROM trustwork.membership WHERE person_id = v_person AND company_id = p_company AND status = 'active'))
    OR (p_connection IS NOT NULL AND NOT EXISTS (SELECT 1 FROM trustwork.connection WHERE id = p_connection AND person_id = v_person AND hub_id = p_hub)) THEN
    RAISE EXCEPTION 'current authority unavailable' USING ERRCODE = '42501', HINT = 'access.not_found';
  END IF;
  PERFORM trustwork.agent_modules_lock_epochs(p_hub,p_company,v_person,p_connection);
END $$;
REVOKE ALL ON FUNCTION trustwork.agent_modules_lock_current_authority(uuid,uuid,uuid) FROM PUBLIC,trustwork_worker;
GRANT EXECUTE ON FUNCTION trustwork.agent_modules_lock_current_authority(uuid,uuid,uuid) TO trustwork_app;

-- These invoker functions expose only shipped public registry metadata; resource authorization stays in the gate.
GRANT EXECUTE ON FUNCTION trustwork.agent_modules_capability_binding(uuid,text),trustwork.agent_modules_effect_binding(uuid,text,text,text) TO trustwork_app;

-- Runtime readers have no UPDATE grant on consent/mandate rows. This narrow owner-only lock port does not return
-- another party's consent or accept a caller-supplied person. Revocation writes conflict with these row locks.
CREATE FUNCTION trustwork.agent_modules_lock_connection_consent(p_connection uuid) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = trustwork, pg_temp SET trustwork.maintenance = 'on' AS $$
DECLARE c trustwork.connection%ROWTYPE; v_consent trustwork.connection_consent%ROWTYPE; b jsonb; v_mandate trustwork.mandate%ROWTYPE;
BEGIN
  SELECT * INTO c FROM trustwork.connection WHERE id=p_connection AND person_id=trustwork.current_person_id() AND surface='participant' AND status='active';
  IF c.id IS NULL THEN RETURN false; END IF;
  SELECT * INTO v_consent FROM trustwork.connection_consent WHERE id=c.consent_id AND person_id=c.person_id FOR SHARE;
  IF v_consent.id IS NULL OR v_consent.withdrawn_at IS NOT NULL OR v_consent.expires_at<=clock_timestamp() OR NOT v_consent.step_up THEN RETURN false; END IF;
  FOR b IN SELECT x FROM jsonb_array_elements(v_consent.mandate_bindings) x ORDER BY x ->> 'mandateId' LOOP
    SELECT * INTO v_mandate FROM trustwork.mandate WHERE id=(b ->> 'mandateId')::uuid AND principal_person_id=c.person_id FOR SHARE;
    IF v_mandate.id IS NULL OR v_mandate.status<>'active' OR v_mandate.revision<>(b ->> 'revision')::integer OR v_mandate.valid_until<=clock_timestamp() THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
END $$;
REVOKE ALL ON FUNCTION trustwork.agent_modules_lock_connection_consent(uuid) FROM PUBLIC,trustwork_worker;
GRANT EXECUTE ON FUNCTION trustwork.agent_modules_lock_connection_consent(uuid) TO trustwork_app;
CREATE TRIGGER agent_effect_handler_immutable BEFORE UPDATE OR DELETE ON trustwork.agent_effect_handler
  FOR EACH ROW EXECUTE FUNCTION trustwork.forbid_mutation();
